// Rebuild the copy/paste installation from versioned sources. No secrets needed.
import { readFile, writeFile, mkdir, copyFile } from 'node:fs/promises';
import { dirname, resolve, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Script } from 'node:vm';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const output = join(root, 'local-delivery');
const sources = ['InspectCopy.gs', 'RegistrationPreview.gs', 'CharacterEdit.gs', 'OtherRegistryForms.gs', 'RegistrationWriteTest.gs', 'WebGateway.gs'];
const parts = [
  '// Generated by npm run build:apps-script. Edit apps-script/ sources, not this file.',
  '// RPTH: shared Admin account; TEST COPY ONLY.',
  '// Replace Code.gs; remove old RegistrationPreview, CharacterEdit, OtherRegistryForms, RegistrationWriteTest and WebGateway files to avoid duplicate functions.'
];
for (const source of sources) {
  const code = (await readFile(join(root, 'apps-script', source), 'utf8'))
    .replace('// Add as a SECOND script file. Keep Code.gs from the inspection step.', '')
    .replace('// Keep Code.gs and RegistrationPreview.gs. No web app endpoints are provided.', '');
  parts.push(`// Source: apps-script/${source}\n${code}`);
}
const bundle = parts.join('\n\n') + '\n';
new Script(bundle, { filename: 'Code.gs' });
const functions = [...bundle.matchAll(/^function (\w+)\s*\(/gm)].map(match => match[1]);
if (new Set(functions).size !== functions.length) throw new Error('Duplicate top-level function names in Apps Script bundle');
JSON.parse(await readFile(join(root, 'apps-script/appsscript.json'), 'utf8'));
await mkdir(output, { recursive: true });
await writeFile(join(output, 'Code.gs'), bundle, 'utf8');
await copyFile(join(root, 'apps-script/appsscript.json'), join(output, 'appsscript.json'));
await writeFile(join(output, 'INSTALL.txt'), [
  'RPTH Apps Script installation — shared Admin account / test copy only',
  '',
  '1. Open the EXISTING Apps Script project attached to the agreed test copy.',
  '2. Replace all contents of Code.gs with this generated Code.gs.',
  '3. Remove old RegistrationPreview, CharacterEdit, OtherRegistryForms, RegistrationWriteTest and WebGateway script files.',
  '4. Set appsscript.json to the generated manifest if needed. Preserve Script Properties.',
  '5. Save. Deploy > Manage deployments > Edit > New version > Deploy.',
  '6. Keep the existing /exec URL and RPTH_GATEWAY_SECRET. Do not generate a new key.',
  '',
  'Do not paste files from tools/apps-script/diagnostics unless diagnosing a problem.',
  'Do not target the main spreadsheet or perform test writes without authorization.',
  'See CODEX_HANDOFF.md for verified status, remaining rules and deployment details.',
  ''
].join('\n'), 'utf8');
console.log(`Built local-delivery/Code.gs (${functions.length} unique functions), appsscript.json and INSTALL.txt`);
